//! The anole-zig agent skill (skills/anole-zig/), embedded in the CLI: `anole
//! new` and `anole init` write it into the project as .claude/skills/anole-zig/.
//! `apis` is its list of public names, which tests/skill_apis_test.zig resolves.
//! This file is generated by `python3 tools/anole/gen_index.py` (rerun it when
//! a file is added or renamed); a test in tools/anole/main.zig fails on a file
//! it does not list.

pub const File = struct {
    /// Relative to the skill's directory, '/'-separated.
    path: []const u8,
    /// The file's bytes, written as they are.
    data: []const u8,
};

pub const apis = @embedFile("anole-zig/apis.txt");

